const express = require('express');
const Joi = require('joi');
const { ApiKeyRegistry, ProjectMembership } = require('../services/apiKeys');

const app = express();
app.use(express.json());

const revokeKeySchema = Joi.object({
  keyId: Joi.string().uuid().required(),
  projectId: Joi.string().alphanum().min(5).max(30).required()
});

const validateRevocation = (req, res, next) => {
  const { error, value } = revokeKeySchema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }
  req.validatedPayload = value;
  next();
};

app.delete('/api/developer/api-keys', validateRevocation, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Developer authentication required' });
  }

  const { keyId, projectId } = req.validatedPayload;

  // Verify that the caller is an owner or admin of the project
  const isAuthorized = await ProjectMembership.checkAdminAccess(req.user.id, projectId);
  if (!isAuthorized) {
    return res.status(403).json({ error: 'Access denied: not an admin of this project' });
  }

  const deleted = await ApiKeyRegistry.revokeKey(keyId, projectId);
  if (!deleted) {
    return res.status(404).json({ error: 'API key not found on project' });
  }

  res.json({ success: true, message: 'API key revoked' });
});

app.listen(7004);
